-- ════════════════════════════════════════════════════════════════════
-- 20260626e — align NOT NULL constraints to the cloud (fix partial imports)
-- ════════════════════════════════════════════════════════════════════
-- UPGRADE installs accumulated stricter legacy NOT NULL constraints than the
-- cloud schema. The import code (identical everywhere) supplies exactly what the
-- CLOUD requires, so it succeeds on a Mac/cloud-aligned DB but silently drops
-- whole entities (sales/purchase invoices, movements, stock) on an older install
-- whose legacy columns reject the rows. This keeps NOT NULL ONLY on columns the
-- cloud genuinely requires (NOT NULL + no default) and relaxes every stricter
-- one. Tolerant + idempotent; PK/required columns are preserved.
DO $$
DECLARE r RECORD;
BEGIN
  FOR r IN
    SELECT c.table_name AS t, c.column_name AS col
    FROM information_schema.columns c
    JOIN information_schema.tables tb
      ON tb.table_schema=c.table_schema AND tb.table_name=c.table_name AND tb.table_type='BASE TABLE'
    WHERE c.table_schema='public' AND c.is_nullable='NO'
      AND NOT EXISTS (SELECT 1 FROM public._cloud_required_cols k WHERE k.t=c.table_name AND k.col=c.column_name)
  LOOP
    BEGIN EXECUTE format('ALTER TABLE public.%I ALTER COLUMN %I DROP NOT NULL', r.t, r.col);
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END LOOP;
  DROP TABLE IF EXISTS public._cloud_required_cols;
END $$;
